const t={maxFlow:{intro:{t:0,b:{t:2,i:[{t:3}],s:"핫엔드가 지속할 수 있는 최대 체적 유량(mm³/s)을 찾습니다 - 유량을 점차 높이면서 익스트루더의 StallGuard 부하를 지켜보다 기어가 미끄러지는 순간을 포착합니다. 먼저 계획을 미리 확인하세요. 실시간 테스트는 가열과 압출을 수행하므로, 실행 전에 프린터를 준비해 두세요."}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"도움말"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Max-Flow 소개"}},close:{t:0,b:{t:2,i:[{t:3}],s:"닫기"}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:"사용 방법"}},steps:[{t:0,b:{t:2,i:[{t:3}],s:"테스트 온도와 필라멘트 지름을 설정하세요(핫엔드를 선택하면 자동 입력됩니다)."}},{t:0,b:{t:2,i:[{t:3}],s:"계획을 미리 확인하세요 - 모든 유량 단계와 압출되는 필라멘트 양이 표시됩니다."}},{t:0,b:{t:2,i:[{t:3}],s:"안전 체크리스트에 표시한 뒤 실시간 테스트를 실행하세요(가열 + 압출)."}},{t:0,b:{t:2,i:[{t:3}],s:"지속 가능한 최대 유량을 확인하고 권장 슬라이서 값을 복사하세요."}}],topics:{howItWorks:{title:{t:0,b:{t:2,i:[{t:3}],s:"테스트 작동 방식"}},body:{t:0,b:{t:2,i:[{t:3}],s:"익스트루더가 체적 유량을 꾸준히 높여가며 필라멘트를 밀어냅니다. 호브드 기어가 깔끔하게 맞물리는 동안에는 StallGuard 부하값이 안정적으로 유지되지만, 미끄러지기 시작하면 값이 요동칩니다. 그 요동 직전에 도달한 최고 유량이 지속 가능한 최대 유량입니다. 미끄러짐이 감지되는 즉시 램프가 중단되므로, 첫 미끄러짐 이후로 필라멘트가 갈리지 않습니다."}}},stallguard:{title:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard 미끄러짐 감지"}},body:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard는 모터 부하를 보고하는 TMC 드라이버 기능입니다. 이 테스트는 유량 단계마다 여러 번 표본을 수집해, 분산(IQR)이나 변동(CV)이 급격히 커지는 지점 - 기어가 그립을 잃는 신호 - 을 찾습니다. 임계값은 드라이버별 프로필에서 가져옵니다. 참고: TMC2209 익스트루더에서는 실험적인 SG4 경로를 사용하므로, 첫 실행은 보정으로 간주하세요."}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"안전"}},body:{t:0,b:{t:2,i:[{t:3}],s:"이 테스트는 익스트루더를 의도적으로 미끄러지게 만드는 뜨겁고 움직이는 작업입니다. 필라멘트를 장착하고, 노즐 주변이 깨끗한지(베드 위나 폐기 영역 위) 확인한 뒤 곁에 머무세요. 프린터가 출력 중일 때는 실행이 거부되며, 끝나면 히터는 항상 꺼집니다."}}},slicer:{title:{t:0,b:{t:2,i:[{t:3}],s:"결과 활용"}},body:{t:0,b:{t:2,i:[{t:3}],s:'권장 값을 슬라이서의 "최대 체적 속도"(필라멘트별)에 입력하세요. 보수적인 수치(측정 최댓값의 80%)는 일상적으로 안전한 한계이고, 균형 수치(90%)는 조금 더 밀어붙입니다. 핫엔드 온도를 높이면 보통 달성 가능한 유량이 올라갑니다.'}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"용어집"}},body:{t:0,b:{static:"",t:2,i:[]}}}},glossary:{flow:{term:{t:0,b:{t:2,i:[{t:3}],s:"체적 유량"}},def:{t:0,b:{t:2,i:[{t:3}],s:"핫엔드가 초당 녹이는 플라스틱 양(mm³/s) - 빠른 출력의 실제 속도 한계입니다."}}},stallguard:{term:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard"}},def:{t:0,b:{t:2,i:[{t:3}],s:"모터의 기계적 부하를 보고하는 TMC 드라이버 신호로, 여기서는 익스트루더 미끄러짐을 감지하는 데 사용됩니다."}}},slip:{term:{t:0,b:{t:2,i:[{t:3}],s:"미끄러짐"}},def:{t:0,b:{t:2,i:[{t:3}],s:"익스트루더 기어가 필라멘트를 충분히 빠르게 잡지 못하고 헛도는 현상 - 유량의 상한입니다."}}},meltzone:{term:{t:0,b:{t:2,i:[{t:3}],s:"용융 구간"}},def:{t:0,b:{t:2,i:[{t:3}],s:"핫엔드의 가열된 길이로, 용융 구간이 길수록(예: Volcano) 더 높은 유량을 지속할 수 있습니다."}}}}},params:{title:{t:0,b:{t:2,i:[{t:3}],s:"테스트 매개변수"}},temperature:{t:0,b:{t:2,i:[{t:3}],s:"온도 (°C)"}},filamentDiameter:{t:0,b:{t:2,i:[{t:3}],s:"필라멘트 Ø (mm)"}},hotend:{t:0,b:{t:2,i:[{t:3}],s:"핫엔드 (선택)"}},hotendNone:{t:0,b:{t:2,i:[{t:3}],s:"- 없음 -"}},hotendHint:{t:0,b:{t:2,i:[{t:3,v:"예상 ~"},{t:4,k:"flow"},{t:3,v:" mm³/s"}]}},startFlow:{t:0,b:{t:2,i:[{t:3}],s:"시작 유량 (mm³/s)"}},endFlow:{t:0,b:{t:2,i:[{t:3}],s:"종료 유량 (mm³/s)"}},stepFlow:{t:0,b:{t:2,i:[{t:3}],s:"단계 (mm³/s)"}},samples:{t:0,b:{t:2,i:[{t:3}],s:"단계당 표본 수"}},extrudePerStep:{t:0,b:{t:2,i:[{t:3}],s:"단계당 압출 (mm)"}},driver:{t:0,b:{t:2,i:[{t:3}],s:"익스트루더 드라이버"}},driverDetected:{t:0,b:{t:2,i:[{t:3}],s:"프린터에서 감지됨"}},autoStealthchop:{t:0,b:{t:2,i:[{t:3}],s:"테스트를 위해 StealthChop 자동 활성화"}},autoStealthchopHint:{t:0,b:{t:2,i:[{t:3}],s:"TMC2209/2240 전용: StallGuard가 값을 읽을 수 있도록 익스트루더에 stealthchop_threshold를 임시로 기록한 뒤, 테스트가 끝나면 주석 처리합니다. printer.cfg를 복원하며, 각 방향마다 펌웨어를 재시작합니다."}},method:{t:0,b:{t:2,i:[{t:3}],s:"감지 방식"}},methodHint:{t:0,b:{t:2,i:[{t:3}],s:"Auto는 StallGuard를 사용하며, StallGuard가 값을 읽지 못하면 툴헤드 가속도계(진동)로 대체합니다. 가속도계 방식은 실험적입니다."}}},method:{auto:{t:0,b:{t:2,i:[{t:3}],s:"Auto"}},stallguard:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard"}},accel:{t:0,b:{t:2,i:[{t:3}],s:"가속도계"}}},plan:{button:{t:0,b:{t:2,i:[{t:3}],s:"계획 미리 보기"}},title:{t:0,b:{t:2,i:[{t:3}],s:"계획된 램프"}},stepCount:{t:0,b:{t:2,i:[{t:4,k:"count"},{t:3,v:"단계"}]}},totalExtrude:{t:0,b:{t:2,i:[{t:3,v:"필라멘트 "},{t:4,k:"mm"},{t:3,v:" mm"}]}},sgField:{t:0,b:{t:2,i:[{t:3,v:"StallGuard 필드: "},{t:4,k:"field"}]}},sgFieldUnknown:{t:0,b:{t:2,i:[{t:3}],s:"이 드라이버에 알려진 StallGuard 필드 없음"}},flowHead:{t:0,b:{t:2,i:[{t:3}],s:"유량 (mm³/s)"}},feedrateHead:{t:0,b:{t:2,i:[{t:3}],s:"이송 속도 (mm/min)"}},warning:{t:0,b:{t:2,i:[{t:3}],s:"실시간 테스트는 핫엔드를 가열하고 의도적으로 미끄러질 때까지 필라멘트를 압출합니다. 미리 보기일 뿐 - 아직 아무것도 실행되지 않습니다."}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"실행 전 - 안전 체크리스트"}},items:[{t:0,b:{t:2,i:[{t:3}],s:"필라멘트가 장착되어 있고 막힘 없이 공급됩니다."}},{t:0,b:{t:2,i:[{t:3}],s:"노즐 주변이 깨끗합니다 - 베드 위나 폐기통 위이며, 출력물 위 공중이 아닙니다."}},{t:0,b:{t:2,i:[{t:3}],s:"일부 필라멘트가 의도적으로 갈리거나 미끄러진다는 점을 받아들입니다."}},{t:0,b:{t:2,i:[{t:3}],s:"테스트 내내 프린터 곁에 있겠습니다."}}],ack:{t:0,b:{t:2,i:[{t:3}],s:"위 사항을 모두 완료했으며 프린터가 준비되었습니다"}},note:{t:0,b:{t:2,i:[{t:3}],s:"출력 중에는 실행이 거부되며, 끝나면 히터가 자동으로 꺼집니다."}}},run:{button:{t:0,b:{t:2,i:[{t:3}],s:"실시간 테스트 실행"}},running:{t:0,b:{t:2,i:[{t:3}],s:"실행 중… (가열 + 압출)"}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:"실시간 max-flow 테스트를 시작할까요?"}},confirmBody:{t:0,b:{t:2,i:[{t:3,v:"핫엔드를 "},{t:4,k:"temp"},{t:3,v:" °C로 가열하고 최대 "},{t:4,k:"mm"},{t:3,v:" mm의 필라멘트를 압출하며, 익스트루더가 미끄러질 때까지 유량을 높입니다."}]}},confirm:{t:0,b:{t:2,i:[{t:3}],s:"지금 실행"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"취소"}},busy:{t:0,b:{t:2,i:[{t:3}],s:"거부됨: 프린터가 사용 중입니다(출력 중 또는 일시정지). 유휴 상태일 때 다시 시도하세요."}},error:{t:0,b:{t:2,i:[{t:3}],s:"테스트에 실패했습니다."}},noSg:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard 표본이 읽히지 않았습니다 - 미끄러짐 결과가 신뢰할 수 없을 수 있습니다. 이 모델에 맞게 드라이버의 라이브 SG 필드를 조정해야 할 가능성이 높습니다."}},progress:{t:0,b:{t:2,i:[{t:4,k:"step"},{t:3,v:"/"},{t:4,k:"total"},{t:3,v:"단계 - "},{t:4,k:"flow"},{t:3,v:" mm³/s"}]}},starting:{t:0,b:{t:2,i:[{t:3}],s:"가열 / 시작 중…"}},abort:{t:0,b:{t:2,i:[{t:3}],s:"실행 중단"}},cancelling:{t:0,b:{t:2,i:[{t:3}],s:"중단 중…"}},cancelled:{t:0,b:{t:2,i:[{t:3}],s:"실행이 중단되었습니다 - 히터가 꺼졌습니다."}},reattached:{t:0,b:{t:2,i:[{t:3}],s:"재연결됨: 페이지를 벗어난 사이에 이 결과가 완료되었습니다."}},failed:{t:0,b:{t:2,i:[{t:3}],s:"Max-flow 실행에 실패했습니다."}},abortNote:{t:0,b:{t:2,i:[{t:3}],s:"중단하면 항상 히터가 꺼집니다."}},parkNote:{t:0,b:{t:2,i:[{t:3}],s:"가열 전에 프린터는 (필요 시) 호밍하고 시야 확보를 위해 노즐을 중앙으로 이동합니다."}},phase:{enabling:{t:0,b:{t:2,i:[{t:3}],s:"StealthChop 활성화 중…"}},homing:{t:0,b:{t:2,i:[{t:3}],s:"프린터 호밍 중…"}},centering:{t:0,b:{t:2,i:[{t:3}],s:"노즐 중앙 정렬 중…"}},heating:{t:0,b:{t:2,i:[{t:3}],s:"핫엔드 가열 중…"}},checking:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard 신호 확인 중…"}},ramp:{t:0,b:{t:2,i:[{t:3}],s:"유량 상승 중…"}},reverting:{t:0,b:{t:2,i:[{t:3}],s:"설정 복원 중…"}}},step:{home:{t:0,b:{t:2,i:[{t:3}],s:"호밍"}},center:{t:0,b:{t:2,i:[{t:3}],s:"중앙 정렬"}},heat:{t:0,b:{t:2,i:[{t:3}],s:"가열"}},check:{t:0,b:{t:2,i:[{t:3}],s:"확인"}},ramp:{t:0,b:{t:2,i:[{t:3}],s:"램프"}}}},camera:{title:{t:0,b:{t:2,i:[{t:3}],s:"실시간 카메라"}},live:{t:0,b:{t:2,i:[{t:3}],s:"LIVE"}},error:{t:0,b:{t:2,i:[{t:3}],s:"카메라를 사용할 수 없습니다."}},willShow:{t:0,b:{t:2,i:[{t:3}],s:"테스트 중 노즐을 보여주는 실시간 카메라 화면이 표시됩니다."}},minimize:{t:0,b:{t:2,i:[{t:3}],s:"최소화"}},maximize:{t:0,b:{t:2,i:[{t:3}],s:"최대화"}},enlarge:{t:0,b:{t:2,i:[{t:3}],s:"확대"}},shrink:{t:0,b:{t:2,i:[{t:3}],s:"축소"}}},result:{title:{t:0,b:{t:2,i:[{t:3}],s:"결과"}},maxFlow:{t:0,b:{t:2,i:[{t:3}],s:"지속 가능한 최대 유량"}},slipAt:{t:0,b:{t:2,i:[{t:4,k:"flow"},{t:3,v:" mm³/s에서 미끄러짐 감지"}]}},noSlip:{t:0,b:{t:2,i:[{t:3}],s:"테스트한 최고 유량까지 미끄러짐 없음"}},reason:{t:0,b:{t:2,i:[{t:3}],s:"상세"}},recommendTitle:{t:0,b:{t:2,i:[{t:3}],s:"권장 슬라이서 값(최대 체적 속도)"}},conservative:{t:0,b:{t:2,i:[{t:3}],s:"보수적 (80%)"}},balanced:{t:0,b:{t:2,i:[{t:3}],s:"균형 (90%)"}},units:{t:0,b:{t:2,i:[{t:3}],s:"mm³/s"}},fromBefore:{t:0,b:{t:2,i:[{t:3,v:"이전에 측정됨("},{t:4,k:"at"},{t:3,v:") - 최신 수치를 얻으려면 다시 실행하세요."}]}},unreliableTitle:{t:0,b:{t:2,i:[{t:3}],s:"신뢰 불가 - StallGuard 신호 없음"}},unmeasured:{t:0,b:{t:2,i:[{t:3}],s:"도달했으나 확인되지 않음"}},via:{t:0,b:{t:2,i:[{t:4,k:"method"},{t:3,v:"(으)로 측정됨"}]}},accelExperimental:{t:0,b:{t:2,i:[{t:3}],s:"진동(가속도계)으로 측정됨 - 실험적이므로 정확한 상한이 아닌 참고 수치로 보세요."}}},states:{loadingHotends:{t:0,b:{t:2,i:[{t:3}],s:"핫엔드 불러오는 중…"}}}}};export{t as default};
